CREATE TABLE d_icd_diagnoses (
  icd_code    VARCHAR(10),   -- mã ICD
  icd_version INT,           -- 9 hoặc 10
  long_title  VARCHAR(300)   -- tên đầy đủ của bệnh bằng tiếng Anh
);
-- JOIN: diagnoses_icd d JOIN d_icd_diagnoses di ON d.icd_code = di.icd_code AND d.icd_version = di.icd_version

CREATE TABLE d_icd_procedures (
  icd_code    VARCHAR(10),
  icd_version INT,
  long_title  VARCHAR(300)
);
-- JOIN: procedures_icd p JOIN d_icd_procedures di ON p.icd_code = di.icd_code AND p.icd_version = di.icd_version

CREATE TABLE d_hcpcs (
  code                VARCHAR(10) PRIMARY KEY,  -- mã HCPCS/CPT
  category            INT,                      -- phân loại dịch vụ
  long_description    VARCHAR(500),              -- mô tả chi tiết
  short_description   VARCHAR(200)               -- mô tả ngắn
);

CREATE TABLE provider (
  provider_id   VARCHAR(10) PRIMARY KEY   -- mã ẩn danh nhân viên y tế
);

CREATE TABLE caregiver (
  caregiver_id    INT PRIMARY KEY   -- mã ẩn danh nhân viên ICU
);
